// ATOW Action Check dice (Fumble / Stunning Success) live in the module: see scripts/lib/rolls.js
const rollActionCheck = game.modules.get("mechwarrior-rpg-homebrew")?.api?.rolls?.rollActionCheck;
if (!rollActionCheck) return ui.notifications.error("Mechwarrior RPG Homebrew must be active to use this macro.");

let dialogContent = `
  <form>
    <div class="form-group">
      <label>WIL Value:</label>
      <input type="number" name="attributeValue" value="0"/>
    </div>
    <div class="form-group">
      <label>Additional Modifiers:</label>
      <input type="number" name="modifiers" value="0"/>
    </div>
  </form>
`;

new Dialog({
  title: "WIL Attribute Check",
  content: dialogContent,
  buttons: {
    roll: {
      label: "Roll",
      callback: async (html) => {
        let attr = (parseInt(html.find('[name="attributeValue"]').val()) || 0);
        let mod = (parseInt(html.find('[name="modifiers"]').val()) || 0);
        const check = await rollActionCheck("@attr + @mod", { attr, mod });
        let roll = check.roll;
        let margin = check.margin(12);
        let result = getMarginDescription(margin);
        roll.toMessage({
          speaker: ChatMessage.getSpeaker(),
          content: `WIL Check<br>WIL: ${attr} + ${mod}<br>Roll: ${check.total}<br>Margin: ${margin}<br>${result}${check.note}`
        });
      }
    }
  }
}).render(true);

function getMarginDescription(margin) {
  if (margin >= 7) return "Spectacular";
  else if (margin >= 5) return "Extraordinary";
  else if (margin >= 3) return "Good";
  else if (margin >= 1) return "It'll do...";
  else if (margin === 0) return "Barely made it!";
  else if (margin >= -2) return "Almost...";
  else if (margin >= -4) return "Bad";
  else if (margin >= -6) return "Terrible";
  else return "Disastrous";
}

// Prompt the user to choose the type of initiative roll
new Dialog({
    title: "Initiative Roll",
    content: `
    <form>
        <div class="form-group">
            <label>Initiative Type:</label>
            <select id="initiative-type" name="initiative-type">
                <option value="basic">Basic Initiative (2d6)</option>
                <option value="combat-paralysis">Initiative (Combat Paralysis) (3d6, choose lowest 2)</option>
                <option value="combat-sense">Initiative (Combat Sense) (3d6, choose highest 2)</option>
            </select>
        </div>
        <div class="form-group">
            <label>Tactics Skill:</label>
            <input type="number" id="tactics-skill" name="tactics-skill" value="0">
        </div>
        <div class="form-group">
            <label>Leadership Skill:</label>
            <input type="number" id="leadership-skill" name="leadership-skill" value="0">
        </div>
    </form>
    `,
    buttons: {
        roll: {
            icon: "<i class='fas fa-dice'></i>",
            label: "Roll",
            callback: async (html) => {
                const initiativeType = html.find('[name="initiative-type"]').val();
                const tacticsSkill = parseInt(html.find('[name="tactics-skill"]').val()) || 0;
                const leadershipSkill = parseInt(html.find('[name="leadership-skill"]').val()) || 0;

                let rollFormula = "";
                let rollDescription = "";

                switch (initiativeType) {
                    case "basic":
                        rollFormula = "2d6";
                        rollDescription = "Basic";
                        break;
                    case "combat-paralysis":
                        rollFormula = "3d6kl2";
                        rollDescription = "Combat Paralysis";
                        break;
                    case "combat-sense":
                        rollFormula = "3d6kh2";
                        rollDescription = "Combat Sense";
                        break;
                }

                // Roll the dice
                let roll = new Roll(`${rollFormula} + @tactics + @leadership`, {
                    tactics: tacticsSkill,
                    leadership: leadershipSkill
                });
                await roll.evaluate();

                // Send the result to chat
                roll.toMessage({
                    speaker: ChatMessage.getSpeaker(),
                    flavor: `Initiative Roll (${rollDescription})`
                });

                // Add the result to the Combat Tracker (selected token, else your character)
                const setInitiative = game.combat?.combatants.find(c => c.tokenId === canvas.tokens.controlled[0]?.id)
                    ?? game.combat?.combatants.find(c => c.actorId === game.user.character?.id);
                if (setInitiative) await game.combat.setInitiative(setInitiative.id, roll.total);
            }
        },
        cancel: {
            icon: "<i class='fas fa-times'></i>",
            label: "Cancel"
        }
    },
    default: "roll"
}).render(true);

