// ATOW melee damage: BD + Margin-of-Success bonus (+1 per 4 MoS, rounded DOWN for melee),
// reduced by (BAR - AP) only when the armor's BAR is higher than the attack's AP. Never below 0.
function meleeDamage(bd, margin, ap, bar) {
  return Math.max(bd + Math.floor(Math.max(margin, 0) * 0.25) - Math.max(bar - ap, 0), 0);
}

