new Dialog({
  title: "Melee Combat",
  content: dialogContent,
  buttons: {
    roll: {
      label: "Roll",
      callback: async (html) => {
        // PC Roll
        let skill_char1 = html.find('[name="skill_char1"]').val();
        let skillLevel_char1 = (parseInt(html.find('[name="skillLevel_char1"]').val()) || 0);
        let link_char1 = (parseInt(html.find('[name="link_char1"]').val()) || 0);
        let complexity_char1 = (parseInt(html.find('[name="complexity_char1"]').val()) || 0);
        let modifiers_char1 = (parseInt(html.find('[name="modifiers_char1"]').val()) || 0);
        let naturalAptitude_char1 = html.find('[name="naturalAptitude_char1"]').is(':checked');
        const check_char1 = await rollActionCheck("@skillLevel + @link + @modifiers", {skillLevel: skillLevel_char1, link: link_char1, modifiers: modifiers_char1}, naturalAptitude_char1);
        let roll_char1 = check_char1.roll;
        await roll_char1.toMessage();

        let result_char1 = check_char1.total;
        let margin_char1 = check_char1.margin(complexity_char1); // Target Number based on Complexity

        let bd_char1 = (parseInt(html.find('[name="bd_char1"]').val()) || 0);
        let ap_char1 = (parseInt(html.find('[name="ap_char1"]').val()) || 0);
        let bar_char1 = (parseInt(html.find('[name="bar_char1"]').val()) || 0);

        // NPC Roll
        let skill_char2 = html.find('[name="skill_char2"]').val();
        let skillLevel_char2 = (parseInt(html.find('[name="skillLevel_char2"]').val()) || 0);
        let link_char2 = (parseInt(html.find('[name="link_char2"]').val()) || 0);
        let complexity_char2 = (parseInt(html.find('[name="complexity_char2"]').val()) || 0);
        let modifiers_char2 = (parseInt(html.find('[name="modifiers_char2"]').val()) || 0);
        let naturalAptitude_char2 = html.find('[name="naturalAptitude_char2"]').is(':checked');
        const check_char2 = await rollActionCheck("@skillLevel + @link + @modifiers", {skillLevel: skillLevel_char2, link: link_char2, modifiers: modifiers_char2}, naturalAptitude_char2);
        let roll_char2 = check_char2.roll;
        await roll_char2.toMessage();

        let result_char2 = check_char2.total;
        let margin_char2 = check_char2.margin(complexity_char2); // Target Number based on Complexity

        let bd_char2 = (parseInt(html.find('[name="bd_char2"]').val()) || 0);
        let ap_char2 = (parseInt(html.find('[name="ap_char2"]').val()) || 0);
        let bar_char2 = (parseInt(html.find('[name="bar_char2"]').val()) || 0);

        // Calculate Final Damage
        let damage_char1 = 0;
        let damage_char2 = 0;

        if (margin_char1 > margin_char2) {
          damage_char1 = meleeDamage(bd_char1, margin_char1, ap_char1, bar_char1);
        } else if (margin_char2 > margin_char1) {
          damage_char2 = meleeDamage(bd_char2, margin_char2, ap_char2, bar_char2);
        }

        // Determine Winner and Outcome
        let outcome = (margin_char1 === margin_char2) ? "It's a tie!" : (margin_char1 > margin_char2) ? "PC wins!" : "NPC wins!";

        // Display Results with Damage
        let content = `
