          speaker: ChatMessage.getSpeaker(),
          content: content
        });
        if (damage_char1 > 0) await game.modules.get("mechwarrior-rpg-homebrew")?.api?.applyAttackDamage?.({damage: damage_char1});
        else if (damage_char2 > 0) await game.modules.get("mechwarrior-rpg-homebrew")?.api?.applyAttackDamage?.({damage: damage_char2, winner: "defender"});
      }
    }
