let result = roll.total;

// Adjust the result based on the angle of attack (Left -1, Right +1)
const angleOffset = {left: -1, right: 1}[angle] ?? 0;
result += angleOffset;

// Above attacks cannot hit the legs; Below attacks cannot hit the head: re-roll those results
if (angle === "above" && result === 7) {
    // Reroll for Above (Legs)
    roll = await new Roll("2d6").evaluate();
    await roll.toMessage({flavor: "Rerolling for Above (Legs)"});
    result = roll.total;
} else if (angle === "below" && (result === 2 || result === 12)) {
    // Reroll for Below (Head)
    roll = await new Roll("2d6").evaluate();
    await roll.toMessage({flavor: "Rerolling for Below (Head)"});
    result = roll.total;
}

// Clamp the result to be between 2 and 12
if (result < 2) result = 2;
if (result > 12) result = 12;

