// Function to apply damage and effects
async function applyDamageAndEffects(hitLocation, damage, winner = "attacker") {
    let extra = {Standard: 0, Fatigue: 0};
    let location = hitLocations[hitLocation];
    let totalDamage = Math.ceil(damage * location.multiplier);
    let effect = await location.effects();
    createChatMessage(`<b>Hit Location:</b> ${location.name}`);
    createChatMessage(`<b>Damage:</b> ${totalDamage}`);
    if (effect) {
        createChatMessage(`<b>Wound Effect:</b> ${effect.name} - ${effect.description}`);
        if (effect.name === "Dazed" || effect.name === "Internal Damage") {
            let additionalDamage = await roll1d6();
            createChatMessage(`<b>Additional ${effect.damageType} Damage:</b> ${additionalDamage}`);
            extra[effect.damageType] += additionalDamage;
        }
    }
    await game.modules.get("mechwarrior-rpg-homebrew")?.api?.applyAttackDamage?.({damage: totalDamage, winner, extraStandard: extra.Standard, extraFatigue: extra.Fatigue});
}

