                    await applyDamageAndEffects(hitLocation, damage, "attacker");
                } else {
                    createChatMessage(`<b>Winner:</b> NPC`);
                    let damage = Math.max(bd_char2 - (bar_char2 - ap_char2), 0);
                    let hitLocation = await rollMeleeHitLocation();
                    await applyDamageAndEffects(hitLocation, damage, "defender");
                }
            }
        }
    }
}).render(true);

