`;

new Dialog({
  title: "Ranged Combat",
  content: dialogContent,
  buttons: {
    roll: {
      label: "Roll",
      callback: async (html) => {
        let skill = html.find('[name="skill"]').val();
        let skillLevel = (parseInt(html.find('[name="skillLevel"]').val()) || 0);
        let link = (parseInt(html.find('[name="link"]').val()) || 0);
        let complexity = (parseInt(html.find('[name="complexity"]').val()) || 0);
        let additionalModifier = (parseInt(html.find('[name="additionalModifier"]').val()) || 0);
        let rangeModifier = parseInt(html.find('[name="range"]').val()) || 0;
        let naturalAptitude = html.find('[name="naturalAptitude"]').is(':checked');
        let baseDamage = (parseInt(html.find('[name="baseDamage"]').val()) || 0);
        let armorPiercing = (parseInt(html.find('[name="armorPiercing"]').val()) || 0);
        let barrierArmorRating = (parseInt(html.find('[name="barrierArmorRating"]').val()) || 0);
        let burstFire = html.find('[name="burstFire"]').is(':checked');
        let rateOfFire = (parseInt(html.find('[name="rateOfFire"]').val()) || 0);
        if (burstFire && rateOfFire < 1) {
          ui.notifications.warn("Burst-Fire needs a Rate of Fire (RoF) of at least 1; the Burst bonus is capped at RoF.");
          return;
        }

        const check = await rollActionCheck("@skillLevel + @link + @additionalModifier + @rangeModifier", {skillLevel, link, additionalModifier, rangeModifier}, naturalAptitude);
        let roll = check.roll;
        await roll.toMessage({flavor: `Ranged Attack Roll${check.note}`, rollMode: "roll"});

        let result = check.total;
        let margin = check.margin(complexity);

        let hitOrMiss = margin >= 0 ? "Hit" : "Miss";
        let finalDamage = 0;

        if (margin >= 0) {
          // Margin-of-Success bonus: Burst-Fire adds the MoS, capped at the weapon's Rate of Fire (RoF);
          // otherwise +1 per 4 MoS, rounded UP for ranged attacks.
          let mosBonus = burstFire ? Math.min(Math.floor(margin), rateOfFire) : Math.ceil(margin * 0.25);
          // AP vs. BAR: armor only helps when its BAR is higher than the attack's AP,
          // and then reduces damage by the difference (BAR - AP). Damage never drops below 0.
          let armorReduction = Math.max(barrierArmorRating - armorPiercing, 0);
          finalDamage = Math.max(baseDamage + mosBonus - armorReduction, 0);
        }

        ChatMessage.create({
          content: `
            <b>Skill Check (Complexity ${complexity})</b><br>
            Skill: ${skill}<br>
            Roll: ${result}<br>
            Margin: ${margin}<br>
            ${hitOrMiss}<br>
            Base Damage: ${baseDamage}<br>
            Final Damage: ${finalDamage}
          `
        });

        // If the attack is a hit, proceed to determine hit location and apply wound effects
        if (hitOrMiss === "Hit") {
          // Prompt for the angle of attack
          let angle = await new Promise(resolve => {
            new Dialog({
              title: "Hit Location Table",
              content: `
                <form>
                  <div class="form-group">
                    <label>Angle of Attack</label>
                    <select id="attack-angle">
                      <option value="front">Front/Back</option>
                        <option value="left">Left Side</option>
                        <option value="right">Right Side</option>
                        <option value="above">Above</option>
                        <option value="below">Below</option>
                    </select>
                  </div>
                </form>
              `,
              buttons: {
                ok: {
                  label: "OK",
                  callback: html => resolve(html.find("#attack-angle").val())
                }
              }
            }).render(true);
          });

          // Perform the 2d6 roll for hit location
          let hitLocationRoll = await new Roll("2d6").evaluate();
          await hitLocationRoll.toMessage({flavor: "Hit Location Roll", rollMode: "roll"});
          let hitLocationResult = hitLocationRoll.total;

          // Adjust the result based on the angle of attack (Left -1, Right +1)
          hitLocationResult += {left: -1, right: 1}[angle] ?? 0;

          // Above attacks cannot hit the legs; Below attacks cannot hit the head: re-roll those results
          if (angle === "above" && hitLocationResult === 7) {
            // Reroll for Above (Legs)
            hitLocationRoll = await new Roll("2d6").evaluate();
            await hitLocationRoll.toMessage({flavor: "Rerolling for Above (Legs)", rollMode: "roll"});
            hitLocationResult = hitLocationRoll.total;
          } else if (angle === "below" && (hitLocationResult === 2 || hitLocationResult === 12)) {
            // Reroll for Below (Head)
            hitLocationRoll = await new Roll("2d6").evaluate();
            await hitLocationRoll.toMessage({flavor: "Rerolling for Below (Head)", rollMode: "roll"});
            hitLocationResult = hitLocationRoll.total;
          }

          // Clamp the result to be between 2 and 12
          if (hitLocationResult < 2) hitLocationResult = 2;
          if (hitLocationResult > 12) hitLocationResult = 12;

          // Lookup the hit location in the rollable table
          let hitLocationTable = (game.tables.getName("Hit Location Table") ?? (await game.packs.get("mechwarrior-rpg-homebrew.atow-tables")?.getDocuments({ name: "Hit Location Table" }))?.[0]);
          if (!hitLocationTable) return ui.notifications.error("Hit Location Table not found (world table or module compendium).");
          let tableRoll = await hitLocationTable.draw({roll: new Roll(hitLocationResult.toString())});
          let hitLocation = tableRoll.results[0].text;

          // Handle additional rolls for torso and legs
          let subLocationRoll;
          if (hitLocation.includes("Torso")) {
            subLocationRoll = await new Roll("1d6").evaluate();
            await subLocationRoll.toMessage({flavor: "Torso Sub-Location Roll", rollMode: "roll"});
            hitLocation = subLocationRoll.total <= 4 ? "Chest" : "Abdomen";
          } else if (hitLocation.includes("Legs")) {
            subLocationRoll = await new Roll("1d6").evaluate();
            await subLocationRoll.toMessage({flavor: "Legs Sub-Location Roll", rollMode: "roll"});
            hitLocation = subLocationRoll.total <= 3 ? "Left Leg" : "Right Leg";
          }

          // Output the final hit location in chat
          ChatMessage.create({
            content: `
              <b>Hit Location Roll:</b> ${hitLocationRoll.total} (${hitLocationRoll.formula}) <br>
              <b>Hit Location Result:</b> ${hitLocation} <br>
              ${subLocationRoll ? `<b>Sub-Location Roll:</b> ${subLocationRoll.total} (${subLocationRoll.formula}) <br>` : ""}
            `
          });

          // Apply damage multipliers and wound effects based on hit location
          let damageMultiplier = 1;
          let woundEffects = "";

          switch (hitLocation.toLowerCase().replace(' ', '')) {
            case "head":
              damageMultiplier = 2;
              let headRoll = new Roll("1d6");
              await headRoll.evaluate();
              await headRoll.toMessage({flavor: "Head Wound Effect Roll", rollMode: "roll"});
              switch (headRoll.total) {
                case 1:
                case 2:
                case 3:
                case 4:
                  woundEffects = "Dazed: Character suffers 1D6 additional Fatigue damage points.";
                  let dazedRoll = new Roll("1d6");
                  await dazedRoll.evaluate();
                  await dazedRoll.toMessage({flavor: "Dazed Effect Roll", rollMode: "roll"});
                  woundEffects += ` Fatigue Damage: ${dazedRoll.total}`;
                  break;
                case 5:
                  woundEffects = "Deafened: Character suffers critical damage to ear equal to Level 3 Poor Hearing.";
                  break;
                case 6:
                  woundEffects = "Blinded: Character suffers critical damage to eye equal to Level 3 Poor Vision.";
                  break;
              }
              break;
            case "chest":
              let chestRoll = new Roll("1d6");
              await chestRoll.evaluate();
              await chestRoll.toMessage({flavor: "Chest Wound Effect Roll", rollMode: "roll"});
              switch (chestRoll.total) {
                case 4:
                  woundEffects = "Dazed: Character suffers 1D6 additional Fatigue damage points.";
                  let dazedRoll = new Roll("1d6");
                  await dazedRoll.evaluate();
                  await dazedRoll.toMessage({flavor: "Dazed Effect Roll", rollMode: "roll"});
                  woundEffects += ` Fatigue Damage: ${dazedRoll.total}`;
                  break;
                case 5:
                  woundEffects = "Knockdown: Character must make a RFL Attribute Check to avoid falling, applying Injury modifiers.";
                  break;
                case 6:
                  woundEffects = "Internal Damage: Character suffers 1D6 additional Standard damage points. Note: Check for Bleeding.";
                  let internalRoll = new Roll("1d6");
                  await internalRoll.evaluate();
                  await internalRoll.toMessage({flavor: "Internal Damage Effect Roll", rollMode: "roll"});
                  woundEffects += ` Standard Damage: ${internalRoll.total}`;
                  break;
              }
              break;
            case "abdomen":
              let abdomenRoll = new Roll("1d6");
              await abdomenRoll.evaluate();
              await abdomenRoll.toMessage({flavor: "Abdomen Wound Effect Roll", rollMode: "roll"});
              switch (abdomenRoll.total) {
                case 3:
                case 4:
                  woundEffects = "Dazed: Character suffers 1D6 additional Fatigue damage points.";
                  let dazedRoll = new Roll("1d6");
                  await dazedRoll.evaluate();
                  await dazedRoll.toMessage({flavor: "Dazed Effect Roll", rollMode: "roll"});
                  woundEffects += ` Fatigue Damage: ${dazedRoll.total}`;
                  break;
                case 5:
                  woundEffects = "Knockdown: Character must make a RFL Attribute Check to avoid falling, applying Injury modifiers.";
                  break;
                case 6:
                  woundEffects = "Internal Damage: Character suffers 1D6 additional Standard damage points. Note: Check for Bleeding.";
                  let internalRoll = new Roll("1d6");
                  await internalRoll.evaluate();
                  await internalRoll.toMessage({flavor: "Internal Damage Effect Roll", rollMode: "roll"});
                  woundEffects += ` Standard Damage: ${internalRoll.total}`;
                  break;
              }
              break;
            case "leftarm":
            case "rightarm":
              damageMultiplier = 0.5;
              woundEffects = "All actions using affected arm suffer –1 roll modifier (max –2).";
              break;
            case "leftleg":
            case "rightleg":
              damageMultiplier = 0.75;
              woundEffects = "Knockdown: Character must make a RFL Attribute Check to avoid falling, applying Injury modifiers. Reduce all movement by 2 meters/turn (to a min. of 0 meters/turn).";
              break;
            case "lefthand":
            case "righthand":
              damageMultiplier = 0.25;
              woundEffects = "All actions using affected hand suffer –2 roll modifier (max –4).";
              break;
            case "leftfoot":
            case "rightfoot":
              damageMultiplier = 0.25;
              woundEffects = "Knockdown: Character must make a RFL Attribute Check to avoid falling, applying Injury modifiers. Reduce all movement by 1 meter/turn (to a min. of 0 meters/turn).";
              break;
          }

          finalDamage *= damageMultiplier;
          finalDamage = Math.ceil(finalDamage);

          ChatMessage.create({
            content: `
              <b>Final Damage after Multiplier:</b> ${finalDamage}<br>
              <b>Wound Effects:</b> ${woundEffects}
            `
          });
          await game.modules.get("mechwarrior-rpg-homebrew")?.api?.applyAttackDamage?.({damage: finalDamage, effects: woundEffects});
        }
      }
    }
  },
  render: (html) => {
    html.find('[name="skill"]').change(function() {
      let selectedSkill = $(this).val();
      let complexity = skillComplexities[selectedSkill];
      html.find('[name="complexity"]').val(complexity);
