        // Collect and Validate Skills
        for (let i = 1; i <= 9; i++) {
          let name = html.find(`[name="skill-${i}"]`).val();
          let lvl = parseInt(html.find(`[name="level-${i}"]`).val()) || 0;
          if (name) {
            selectedSkills.push(name);
            totalLevel += lvl;
          }
        }

        if (selectedSkills.length < 3) {
          ui.notifications.warn("A Bundled Skill Check requires at least 3 skills.");
          return;
        }

        // Logic variables
        let avgLevel = Math.ceil(totalLevel / selectedSkills.length);
        let additionalMod = parseInt(html.find('[name="additionalModifier"]').val()) || 0;
        let naturalAptitude = html.find('[name="naturalAptitude"]').is(':checked') ? 1 : 0;
        let tn = html.find('[name="clanAptitude"]').is(':checked') ? 7 : 8;

        // Roll: 2d6 Exploding + Avg Level + Modifiers + Aptitude
        const check = await rollActionCheck(`${avgLevel} + ${additionalMod} + ${naturalAptitude}`);
        let roll = check.roll;

        let result = check.total;
        let margin = check.margin(tn);
