        else if (margin === 0) description = "Barely made it!";
        else if (margin >= -2) description = "Almost...";
        else if (margin >= -4) description = "Bad";
        else if (margin >= -6) description = "Terrible";
        else description = "Disastrous";

        // Handle Failure Logic
        let failureText = "";
        if (margin < 0) {
          let moF = Math.abs(margin);
          let actionsFailed = Math.ceil(moF / 2);

          if (isFumble || actionsFailed >= selectedSkills.length) {
            failureText = `<br><strong style="color:red;">FUMBLED: Entire sequence failed from the start.</strong>`;
          } else {
            // Find which skill it failed at (counting back from end)
            let failIndex = selectedSkills.length - actionsFailed;
            let failedSkillName = selectedSkills[failIndex];
            failureText = `<br><strong style="color:orange;">Failed at ${failedSkillName}</strong> (Step ${failIndex + 1})`;
          }
        }

        let content = `
          <div style="font-family: sans-serif;">
            <b>Bundled Skill Check (TN ${tn})</b><br>
            <i>Skills: ${selectedSkills.join(", ")}</i><hr>
