            <b>Roll Total:</b> ${result}<br>
            <b>Margin:</b> ${margin}<br>
            <b>Result:</b> ${description}${check.note}
            ${failureText}
          </div>
        `;

        roll.toMessage({
          speaker: ChatMessage.getSpeaker(),
          content: content
        });
      }
    }
  },
  default: "roll"
}).render(true);

